using namespace std;

class Solution {
public:
    long long splitArrayWithMinimumDifference(vector<int>& nums) {
        long long total_sum = 0;
        for (int x : nums) total_sum += x;
        long long prefix = 0;
        long long min_diff = -1;
        for (int i = 0; i < (int)nums.size() - 1; ++i) {
            prefix += nums[i];
            long long suffix = total_sum - prefix;
            long long diff = abs(prefix - suffix);
            if (min_diff == -1 || diff < min_diff) {
                min_diff = diff;
            }
        }
        return min_diff;
    }
};

class Solution {
    public long splitArrayWithMinimumDifference(int[] nums) {
        long totalSum = 0;
        for (int x : nums) totalSum += x;
        long prefix = 0;
        long minDiff = Long.MAX_VALUE;
        for (int i = 0; i < nums.length - 1; i++) {
            prefix += nums[i];
            long suffix = totalSum - prefix;
            minDiff = Math.min(minDiff, Math.abs(prefix - suffix));
        }
        return minDiff;
    }
}

